check_code:
from fractions import Fraction as F
rows=[(1,20,10,10),(2,15,15,10),(5,20,20,0),(10,12,15,13)]
n={c+i+x for _,c,i,x in rows}
assert n=={40}
avg=F(sum(m*c for m,c,_,_ in rows),40)
opts={'A':F(575,100),'B':F(525,100),'C':F(675,100),'D':F(625,100)}
assert avg==opts['C']
for o in 'ABD': assert avg!=opts[o]

from decimal import Decimal, ROUND_HALF_UP
p=(Decimal(500)/Decimal(720+680+500+450+850)*100).quantize(Decimal('0.01'),rounding=ROUND_HALF_UP)
opts={'A':'14.63','B':'15.78','C':'15.63','D':'14.34'}
assert p==Decimal(opts['C'])
for o in 'ABD': assert p!=Decimal(opts[o])
